mapper.select:
SELECT a.id, a.title, a.item_type, a.category_id, c.name AS category_name, a.author_id, u.display_name AS author_name, a.status, a.event_time, a.location, a.updated_at, a.version FROM cms_article a JOIN cms_category c ON c.id = a.category_id JOIN sys_user u ON u.id = a.author_id WHERE a.deleted = 0 AND a.status = 'PENDING_REVIEW'
AND (a.title LIKE CONCAT('%', #{q.keyword}, '%') OR a.content LIKE CONCAT('%', #{q.keyword}, '%'))
AND a.item_type = #{q.itemType}
AND a.category_id = #{q.categoryId}
AND a.author_id != #{q.excludeAuthorId}
ORDER BY a.updated_at ASC, a.id ASC
